import React from "react";

type BatterData = {
  batter_name: string;
  team: string;
  overall_avg: string;
  last_15: string;
  hand_avg: string;
  vs_hand: string;
  avg: string;
  hits: number;
  at_bats: number;
  ["2b"]: number;
  home_runs: number;
  prevHits: number;
  game_url: string;
};

type Props = {
  data: BatterData[];
};

const BatterTable: React.FC<Props> = ({ data }) => {
  return (
    <table style={{ width: "100%", borderCollapse: "collapse" }}>
      <thead>
        <tr>
          <th>#</th>
          <th>Batter Name</th>
          <th>Overall Avg</th>
          <th>Batter Last 15</th>
          <th>Pitcher Avg vs Hand</th>
          <th>Batter Avg vs Hand</th>
          <th>Avg vs Pitcher</th>
          <th>Hits</th>
          <th>AB</th>
          <th>2B</th>
          <th>HR</th>
          <th>Prev Game Hits</th>
          <th>URL</th>
        </tr>
      </thead>
      <tbody>
        {data.map((batter, index) => (
          <tr key={index}>
            <td style={{ textAlign: "center" }}>{index + 1}</td>
            <td>{`${batter.batter_name} (${batter.team})`}</td>
            <td>{batter.overall_avg}</td>
            <td>{batter.last_15}</td>
            <td>{batter.hand_avg}</td>
            <td>{batter.vs_hand}</td>
            <td>{batter.avg}</td>
            <td>{batter.hits}</td>
            <td>{batter.at_bats}</td>
            <td>{batter["2b"]}</td>
            <td>{batter.home_runs}</td>
            <td>{batter.prevHits}</td>
            <td>
              <a
                href={batter.game_url}
                target="_blank"
                rel="noopener noreferrer"
              >
                Link
              </a>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default BatterTable;
